/// <summary>
/// Contract class for Ready for Pricing business events
/// </summary>
[DataContract]
public final class METSOReadyForPricingBusinessEventContract  extends BusinessEventsContract
{
    private SalesId salesId;

}

Method.Source:
    /// <summary>
    /// Parm method for Sales Id 
    /// </summary>
    /// <param name = "_salesId">Sales Id</param>
    /// <returns>SalesId</returns>
    [DataMember(identifierStr(SalesId)), BusinessEventsDataMember("@AccountsReceivable:SalesOrderId")]
    public SalesId parmSalesOrderId(SalesId _salesId = salesId)
    {
        salesId = _salesId;

        return salesId;
    }

    /// <summary>
    /// Create contract instance using SalesTable
    /// </summary>
    /// <param name = "_salesTable">Salestable</param>
    /// <returns>An instance of <c>METSOReadyForPricingBusinessEventContract</c></returns>
    public static METSOReadyForPricingBusinessEventContract newFromSalesTable(SalesTable _salesTable)
    {
        var contract = new METSOReadyForPricingBusinessEventContract();
        contract.initialize(_salesTable);

        return contract;
    }

/// <summary>
/// Initialize the data contract
/// </summary>
/// <param name = "_salesTable">SalesTable</param>
private void initialize(SalesTable _salesTable)
{
    salesId = _salesTable.SalesId;
}
